graphql.operation:
query PublicFeed {
  feed {
    id
    caption
    imageKey
    createdAt
    author {
      id
      name
      username
      avatarKey
    }
    comments {
      id
      postId
      parentId
      content
      createdAt
      author {
        id
        name
        username
        avatarKey
      }
      replies {
        id
        postId
        parentId
        content
        createdAt
        author {
          id
          name
          username
          avatarKey
        }
      }
    }
  }
}
